import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:onegame/core/rng/seeded_random.dart';

/// Reference values generated by the TypeScript implementation
/// (`functions/scripts/genRngVectors.ts`). Dart and TS must agree exactly.
Map<String, dynamic> _loadVectors() {
  final file = File('../shared/rng_vectors.json');
  return jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
}

List<int> _ints(Object? list) =>
    (list! as List<dynamic>).map((e) => e as int).toList();

void main() {
  final vectors = _loadVectors();

  test('fnv1a32 matches TypeScript', () {
    for (final entry in vectors['hashes'] as List<dynamic>) {
      final m = entry as Map<String, dynamic>;
      expect(fnv1a32(m['label'] as String), m['hash'], reason: '${m['label']}');
    }
  });

  test('mulberry32 sequences match TypeScript', () {
    for (final entry in vectors['sequences'] as List<dynamic>) {
      final m = entry as Map<String, dynamic>;
      final expected = _ints(m['uint32']);
      final r = SeededRandom(m['seed'] as int);
      expect([for (final _ in expected) r.nextUint32()], expected);
    }
  });

  test('derived generators match TypeScript', () {
    for (final entry in vectors['derived'] as List<dynamic>) {
      final m = entry as Map<String, dynamic>;
      final expected = _ints(m['uint32']);
      final r = SeededRandom.derive(m['seed'] as int, m['label'] as String);
      expect([for (final _ in expected) r.nextUint32()], expected);
    }
  });

  test('helpers match TypeScript', () {
    final h = vectors['helpers'] as Map<String, dynamic>;
    final r = SeededRandom(h['seed'] as int);
    final n100 = _ints(h['nextInt100']);
    expect([for (final _ in n100) r.nextInt(100)], n100);
    final range = _ints(h['intInRange_10_20']);
    expect([for (final _ in range) r.intInRange(10, 20)], range);
    expect(r.shuffled(List<int>.generate(10, (i) => i)), _ints(h['shuffled']));
  });

  test('same seed gives same sequence, different seeds differ', () {
    List<int> seq(int seed) {
      final r = SeededRandom(seed);
      return [for (var i = 0; i < 50; i++) r.nextUint32()];
    }

    expect(seq(7), seq(7));
    expect(seq(7), isNot(seq(8)));
  });

  test('derive isolates sub-generators', () {
    final a = SeededRandom.derive(42, 'minigolf:hole1').nextUint32();
    final b = SeededRandom.derive(42, 'minigolf:hole2').nextUint32();
    expect(a, isNot(b));
  });

  test('values stay in range', () {
    final r = SeededRandom(123);
    for (var i = 0; i < 10000; i++) {
      final d = r.nextDouble();
      expect(d >= 0 && d < 1, isTrue);
      final n = r.intInRange(-3, 3);
      expect(n >= -3 && n <= 3, isTrue);
      final u = r.nextUint32();
      expect(u >= 0 && u <= 0xFFFFFFFF, isTrue);
    }
    expect(() => r.nextInt(0), throwsRangeError);
    expect(() => r.pick(<int>[]), throwsStateError);
  });

  test('seed is normalised to 32 bits', () {
    expect(
      SeededRandom(-1).nextUint32(),
      SeededRandom(0xFFFFFFFF).nextUint32(),
    );
  });
}
